import boto3,json,os,time,urllib.request
from botocore.config import Config
print("CONTAINER_STARTED "+json.dumps({"time":time.time(),"sdk":boto3.__version__}),flush=True)
for path in ["","/task"]:
 try:
  with urllib.request.urlopen(os.environ["ECS_CONTAINER_METADATA_URI_V4"]+path,timeout=5) as r:
   print("METADATA "+json.dumps({"path":path,"status":r.status,"body":json.loads(r.read())}),flush=True)
 except Exception as e: print("METADATA_ERROR "+type(e).__name__,flush=True)
try:
 result=boto3.client("sts",region_name="us-east-1",config=Config(connect_timeout=5,read_timeout=10,retries={"max_attempts":1})).get_caller_identity()
 print("STS_IDENTITY "+json.dumps(result),flush=True)
except Exception as e:
 print("STS_ERROR "+json.dumps({"type":type(e).__name__}),flush=True)
 raise SystemExit(2)
time.sleep(10)
print("CONTAINER_EXIT_ZERO",flush=True)

